 import java.io.ByteArrayInputStream;
+import java.io.IOException;
 import java.io.ObjectInputStream;

 public class Example {
     public Object load(byte[] data) throws Exception {
-        ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(data));
-        return in.readObject();
+        try (ObjectInputStream in = new CustomObjectInputStream(new ByteArrayInputStream(data))) {
+            return in.readObject();
+        }
     }
 }
+
+class CustomObjectInputStream extends ObjectInputStream {
+    private static final Class<?>[] ALLOWED_CLASSES = {String.class, Integer.class};
+
+    public CustomObjectInputStream(byte[] data) throws IOException, ClassNotFoundException {
+        super(new ByteArrayInputStream(data));
+    }
+
+    @Override
+    protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
+        for (Class<?> clazz : ALLOWED_CLASSES) {
+            if (clazz.getName().equals(desc.getName())) {
+                return clazz;
+            }
+        }
+        throw new InvalidClassException("Unauthorized deserialization attempt", desc.getName());
+    }
+}

